mapper.select:
SELECT h.hazard_id AS hazardId, h.risk_level AS riskLevel, h.hazard_type AS hazardType, h.coord_x as coord_x, h.coord_y as coord_y, h.update_time as updateTime, g.grid_name AS gridName, a.name AS regionName, h.discover_time AS discoverTime FROM biz_risk_hazard h LEFT JOIN sys_grid_cfg g ON h.region_full_code = g.grid_code LEFT JOIN sys_area a ON h.region_full_code = a.full_code
h.region_full_code = #{regionFullCode}
AND h.risk_level = #{riskLevel}
AND h.hazard_type = #{hazardType}
AND h.discover_time >= #{startTime}
AND h.discover_time <= #{endTime}
